Section KIT3.
  Context {HCEIL : HeapCeil}.
  Lemma land_2047 : forall x, Z.land x 2047 = x mod 2048.
  Proof. intros. change 2047 with (Z.ones 11). rewrite Z.land_ones by lia. reflexivity. Qed.
  Lemma wrap_mod_2048 : forall e, bv_unsigned (Z_to_bv 64 e) mod 2048 = e mod 2048.
  Proof. intros e. exact (unsigned_wrap_mod e 11 ltac:(lia)). Qed.
  (* [comment removed for export] *)
  Lemma shad64_of_words : forall m A, 0 <= A -> A mod 8 = 0 ->
    rw_cells bsegs m (sh A) (repeat (C8 (Z_to_bv 64 0)) 8) -> SHAD m A (poison_bytes 64 0).
  Proof.
    intros m A H0 H8 RC. split; [exact H0|]. split; [exact H8|].
    apply (u8arr_of_rw_cells bsegs m (sh A) 64).
    pose proof (rw_cells_merge bsegs m (sh A) [] (repeat (C8 (Z_to_bv 64 0)) 8) []) as M.
    rewrite app_nil_r in M. cbn [app cells_size csize cells_bytes cbytes Nat.add repeat] in M.
    exact (M RC).
  Qed.
End KIT3.

